--- a/src/seed.rs
+++ b/src/seed.rs
@@ -170,6 +170,16 @@
             seed = mix(seed, box_ptr as usize as u64);
         }

+        // Temporary diagnostic: replay the shared input, retaining native per-table seeds.
+        #[cfg(feature = "std")]
+        let seed = match std::env::var("DELTA_READER_DIAGNOSTIC_SHARED_SEED").as_deref() {
+            Ok("random") => seed,
+            Ok(value) if value.len() == 16 => u64::from_str_radix(value, 16)
+                .expect("DELTA_READER_DIAGNOSTIC_SHARED_SEED must be random or 16 hex digits"),
+            _ => panic!("DELTA_READER_DIAGNOSTIC_SHARED_SEED must be random or 16 hex digits"),
+        };
+        #[cfg(feature = "std")]
+        eprintln!("DELTA_READER_SHARED_SEED={seed:016x}");
         SharedSeed::from_u64(seed)
     }
